#include <Arduino.h>
#include <cstring>
#include "USB.h"

USBCDC console;
char line[48];
size_t lineLength = 0;

void setup() {
  console.begin(115200);
  USB.begin();
}

void loop() {
  while (console.available() > 0) {
    const int value = console.read();
    if (value == '\n' || value == '\r') {
      line[lineLength] = '\0';
      if (lineLength > 0 && std::strcmp(line, "status") == 0) {
        console.println("ready");
      }
      lineLength = 0;
    } else if (value >= 32 && lineLength < sizeof(line) - 1) {
      line[lineLength++] = static_cast<char>(value);
    } else if (lineLength == sizeof(line) - 1) {
      lineLength = 0;
      console.println("command too long");
    }
  }
}

#include <Arduino.h>
#include <SD_MMC.h>
#include <USB.h>
#include <USBMSC.h>
#include <cstring>
#include <freertos/FreeRTOS.h>
#include <freertos/semphr.h>

USBMSC disk;
SemaphoreHandle_t cardLock;
uint32_t sectorCount;
constexpr uint32_t SECTOR_SIZE = 512;

int32_t readSector(uint32_t lba, uint32_t offset,
                   void* output, uint32_t length) {
  if (lba >= sectorCount || offset > SECTOR_SIZE ||
      length > SECTOR_SIZE - offset) return -1;
  uint8_t sector[SECTOR_SIZE];
  if (xSemaphoreTake(cardLock, pdMS_TO_TICKS(1000)) != pdTRUE) return -1;
  const bool ok = SD_MMC.readRAW(sector, lba);
  xSemaphoreGive(cardLock);
  if (!ok) return -1;
  std::memcpy(static_cast<uint8_t*>(output), sector + offset, length);
  return static_cast<int32_t>(length);
}

int32_t writeSector(uint32_t lba, uint32_t offset,
                    uint8_t* input, uint32_t length) {
  if (lba >= sectorCount || offset > SECTOR_SIZE ||
      length > SECTOR_SIZE - offset) return -1;
  uint8_t sector[SECTOR_SIZE];
  if (xSemaphoreTake(cardLock, pdMS_TO_TICKS(1000)) != pdTRUE) return -1;
  bool ok = SD_MMC.readRAW(sector, lba);
  if (ok) {
    std::memcpy(sector + offset, input, length);
    ok = SD_MMC.writeRAW(sector, lba);
  }
  xSemaphoreGive(cardLock);
  return ok ? static_cast<int32_t>(length) : -1;
}

void setup() {
  Serial.begin(115200);
  if (!SD_MMC.begin("/sdcard", true)) {
    Serial.println("SD card initialization failed");
    return;
  }
  sectorCount = static_cast<uint32_t>(SD_MMC.numSectors());
  cardLock = xSemaphoreCreateMutex();
  if (sectorCount == 0 || cardLock == nullptr) {
    Serial.println("SD card geometry or mutex is invalid");
    return;
  }
  disk.onRead(readSector);
  disk.onWrite(writeSector);
  if (!disk.begin(sectorCount, SECTOR_SIZE)) {
    Serial.println("USB MSC start failed");
    return;
  }
  USB.begin();
}

void loop() {}

#include <Arduino.h>
#include "USB.h"
#include "USBMIDI.h"

USBMIDI midi("Button Controller");
constexpr uint8_t BUTTON_PIN = 4;
bool previousPressed = false;

void setup() {
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  midi.begin();
  USB.begin();
}

void loop() {
  const bool pressed = digitalRead(BUTTON_PIN) == LOW;
  if (pressed != previousPressed) {
    delay(20);
    const bool stablePressed = digitalRead(BUTTON_PIN) == LOW;
    if (stablePressed != previousPressed) {
      previousPressed = stablePressed;
      if (stablePressed) midi.noteOn(60, 96);
      else midi.noteOff(60, 0);
    }
  }
}
